function installVisualTheme(){if(!document?.head||document.getElementById?.('ruta-visual-v1'))return false;let style=E('style');style.id='ruta-visual-v1';style.textContent=VISUAL_CSS;document.head.append(style);return true}
const HUMAN_LABELS={MASTERED:'evidencia inicial suficiente',UNKNOWN:'sin datos',PARTIALLY_UNDERSTOOD:'comprensión parcial',MISCONCEPTION:'idea errónea',PARTIAL:'parcial',CORRECT:'correcto',
 EXPLAIN:'Explicación',CHECK:'Comprobación',GUIDED_PRACTICE:'Práctica guiada',INDEPENDENT_PRACTICE:'Práctica independiente',REVIEW:'Repaso',CONFIRMATION:'Confirmación',DIAGNOSTIC:'Diagnóstico',
 TEACH:'Aprender',COMPREHENSION:'Comprobar que entendiste',GUIDED:'Práctica guiada',INDEPENDENT:'Práctica independiente',CHALLENGE:'Reto',INTEGRATION:'Integrar con la meta',CONTEXT:'Reparación',INTEGRATE_WITH_GOAL:'Integrar con la meta',INDEPENDENT_EVIDENCE:'Evidencia independiente',SPACED_REVIEW:'Repaso espaciado',PROBE_PREREQUISITE:'Explorar un prerrequisito',NOT_EVALUATED:'Sin evaluar',MICRO_TUTOR:'Microlección',SATISFIED:'cumplido',NOT_SATISFIED:'no cumplido',option_choice:'Elección de opción',explanation:'Explicación',deterministic_option_key:'clave local de la opción',provider_semantic:'valoración del modelo',recognition:'reconocimiento',variables:'variables',units:'unidades',equation_manipulation:'manejo de ecuaciones',method_selection:'elección del método',contextual_application:'aplicación en contexto',interpretation:'interpretación',memory:'memoria',self_explanation:'autoexplicación',INTEGRATE:'Integrar con la meta',OPEN:'abierta',DIAGNOSING:'buscando la causa',REPAIRING:'reparando',PARENT_RETEST:'volviendo al problema original',TRANSFER_CHECK:'comprobando que se transfiere',COMPLETED:'completada',conceptual:'comprensión',direct_application:'aplicación directa',procedure:'procedimiento',procedural:'procedimiento',transfer:'transferencia',retention:'retención',discrimination:'discriminación',composition:'composición',independence:'independencia',calibration:'calibración',lack_of_exposure:'falta de exposición al tema',careless:'descuido',EVALUATED:'Evaluado',MET:'Cumplido',NOT_MET:'No cumplido'};
const humanLabel=v=>HUMAN_LABELS[v]||String(v??'');const humanReason=text=>String(text||'').replace(/El intento mostró ([a-z_]+)\./g,(m,c)=>'El intento mostró una dificultad de '+humanLabel(c)+'.');
const coverageLabel=status=>humanLabel(status);
const g=()=>store.goals.find(x=>x.id===store.active);
function refreshPersistenceIndicator(){let state=document.getElementById?.('ruta-persistence-state');if(!state||state.id!=='ruta-persistence-state')return;state.textContent=persistenceDirty?'Cambios sin confirmar':pendingWrites?'Guardando…':'Sincronizado';state.className='status-pill '+(persistenceDirty?'bad':pendingWrites?'warn':'good')}
let pendingSave=null;
function save(){if(!activeProfile?.profile_id)return Promise.resolve(false);let snapshot=JSON.parse(JSON.stringify(store)),profileId=activeProfile.profile_id;if(pendingSave&&pendingSave.profileId===profileId){pendingSave.snapshot=snapshot;return pendingSave.job}let entry={profileId,snapshot,job:null};pendingWrites+=1;refreshPersistenceIndicator();entry.job=persistQueue.catch(()=>false).then(async()=>{if(pendingSave===entry)pendingSave=null;try{let result=await api('/api/profile/save',{profile_id:profileId,store:entry.snapshot,expected_revision:revision});revision=result.revision;pendingWrites-=1;persistenceDirty=false;refreshPersistenceIndicator();if(pendingWrites===0&&statusEl.textContent==='Listo. Guardando en segundo plano…')note('Listo.');return true}catch(error){pendingWrites-=1;persistenceDirty=true;refreshPersistenceIndicator();note('No se guardó la memoria durable: '+(error?.message||String(error))+'. El progreso visible puede diferir del disco.',true);return false}});pendingSave=entry;persistQueue=entry.job;return entry.job}
const flushSave=()=>persistQueue;
function note(s,bad=false){statusEl.textContent=s;statusEl.className=bad?'err':'ok';statusEl.setAttribute?.('aria-live',bad?'assertive':'polite');if(s==='Listo.'){let t=setTimeout(()=>{if(statusEl.textContent==='Listo.')statusEl.textContent=''},3000);t?.unref?.()}}
async function api(route,payload={}){let c=new AbortController(),timer=setTimeout(()=>c.abort(),100000),body={...payload};if(activeProfile?.profile_id&&!body.profile_id)body.profile_id=activeProfile.profile_id;try{let r=await fetch(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:c.signal});let d=await r.json();if(!r.ok)throw Error(d.error||'Error del servidor');return d}catch(e){if(e.name==='AbortError')throw Error('La solicitud tardó demasiado; revisa el servidor antes de repetir.');if(e instanceof TypeError)throw Error('No se pudo contactar al servidor local.');throw e}finally{clearTimeout(timer)}}
async function task(label,fn){if(busy)return;busy=true;note(label);try{await fn();if(statusEl.textContent===label&&!persistenceDirty)note(pendingWrites===0?'Listo.':'Listo. Guardando en segundo plano…')}catch(e){note(e?.message||String(e),true);console.error(e)}finally{busy=false}}
function nav(){let bar=E('nav'),brand=E('div','Ruta');bar.className='app-nav';brand.className='nav-brand';bar.ariaLabel='Navegación principal';bar.append(brand);let add=(label,target,action)=>{let button=B(label,action,true);button.className='quiet nav-button';if(page===target)button.setAttribute?.('aria-current','page');bar.append(button)};add('Perfiles','profiles',()=>{page='profiles';render()});if(activeProfile){add('Metas','home',()=>{page='home';render()});add('Aprendizaje','learning',()=>{page='learning';render()});add('Preferencias','preferences',()=>{page='preferences';render()})}if(g()){add('Ruta y mapa','dashboard',()=>{page='dashboard';render()});add('Nivel experto','expert',()=>{page='expert';render()});add('Informe','report',()=>{page='report';render()})}if(persistenceDirty){let retry=B('Reintentar guardado',()=>task('Guardando…',save),true);retry.className='quiet nav-button';bar.append(retry)}app.append(bar);if(activeProfile){let strip=E('div'),goal=g(),state=E('span',persistenceDirty?'Cambios sin confirmar':pendingWrites?'Guardando…':'Sincronizado');strip.className='context-strip';state.id='ruta-persistence-state';state.className='status-pill '+(persistenceDirty?'bad':pendingWrites?'warn':'good');strip.append(E('strong',goal?.goal||'Sin meta activa'),E('span','Perfil: '+activeProfile.name),state);app.append(strip)}}
function downloadJson(value,name){let url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=E('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function backup(){if(!activeProfile)throw Error('Selecciona un perfil.');await flushSave();if(persistenceDirty)throw Error('No se puede exportar hasta que la memoria pendiente se guarde.');downloadJson(await api('/api/profile/export',{}),'ruta-respaldo-durable.json')}
function normalizeImportedStore(raw){
 if(!raw||typeof raw!=='object'||!Array.isArray(raw.goals))throw policyError('INVALID_BACKUP','Este archivo no es un respaldo de Ruta v4.');
 let normalized={...raw,goals:raw.goals.map(normalizeGoal)};
 normalized.goal_relations=normalizeGoalRelations(raw.goal_relations,normalized.goals,raw.profile_id||activeProfile?.profile_id||null);
 if(!normalized.goals.some(x=>x.id===normalized.active))normalized.active=normalized.goals[0]?.id||null;
 return normalized
}
function relationEndpointAvailable(endpoint,goals=store.goals){let goal=(goals||[]).find(x=>x?.id===endpoint?.goal_id);return Boolean(goal&&(goal.nodes||[]).some(node=>node?.id===endpoint?.node_id))}
function normalizeGoalRelation(raw,goals,profileId){
 if(!raw||raw.schema_version!==GOAL_RELATION_VERSION)throw policyError('INVALID_GOAL_RELATION','La relación no tiene una versión compatible.');
 let relationId=String(raw.relation_id||'').trim(),relationProfile=String(raw.profile_id||profileId||'').trim(),source={goal_id:String(raw.source?.goal_id||'').trim(),node_id:String(raw.source?.node_id||'').trim()},target={goal_id:String(raw.target?.goal_id||'').trim(),node_id:String(raw.target?.node_id||'').trim()},type=String(raw.type||'').trim(),status=String(raw.status||'').trim(),explanation=String(raw.explanation||'').trim(),provenance=raw.provenance&&typeof raw.provenance==='object'?{...raw.provenance}:null,createdAt=Number(raw.created_at);
 if(!relationId||!relationProfile||relationProfile!==profileId||!source.goal_id||!source.node_id||!target.goal_id||!target.node_id||source.goal_id===target.goal_id)throw policyError('INVALID_GOAL_RELATION','La relación no conserva identidad y extremos inequívocos.');
 if(!GOAL_RELATION_TYPES.includes(type)||!GOAL_RELATION_STATES.includes(status)||!explanation||explanation.length>800||!provenance||!String(provenance.source||'').trim()||!Number.isFinite(createdAt)||createdAt<0)throw policyError('INVALID_GOAL_RELATION','La relación no conserva tipo, estado, procedencia y fecha válidos.');
 let available=relationEndpointAvailable(source,goals)&&relationEndpointAvailable(target,goals);return {...raw,schema_version:GOAL_RELATION_VERSION,relation_id:relationId,profile_id:relationProfile,source,target,type,explanation,provenance,created_at:createdAt,status,endpoint_status:available?'available':'missing'}
}
function normalizeGoalRelations(raw,goals,profileId){let values=Array.isArray(raw)?raw:[],ids=new Set(),result=[];for(let item of values){let relation=normalizeGoalRelation(item,goals,profileId);if(ids.has(relation.relation_id))throw policyError('DUPLICATE_GOAL_RELATION','El respaldo repite un ID de relación.');ids.add(relation.relation_id);result.push(relation)}return result}
function goalRelationCreatesCycle(relations,candidate){if(candidate.type!=='prerequisite')return false;let graph=new Map();for(let relation of [...relations,candidate]){if(relation.type!=='prerequisite'||relation.status==='rejected'||relation.endpoint_status==='missing')continue;if(!graph.has(relation.source.goal_id))graph.set(relation.source.goal_id,new Set());graph.get(relation.source.goal_id).add(relation.target.goal_id)}let start=candidate.target.goal_id,target=candidate.source.goal_id,seen=new Set(),stack=[start];while(stack.length){let current=stack.pop();if(current===target)return true;if(seen.has(current))continue;seen.add(current);for(let next of graph.get(current)||[])stack.push(next)}return false}
function createGoalRelation(input,profileId=activeProfile?.profile_id,goals=store.goals,relations=store.goal_relations||[]){let candidate=normalizeGoalRelation({schema_version:GOAL_RELATION_VERSION,relation_id:String(input?.relation_id||newId('relation')),profile_id:profileId,source:input?.source,target:input?.target,type:input?.type,explanation:input?.explanation,provenance:input?.provenance||{source:'manual'},created_at:input?.created_at??now(),status:input?.status||'proposed'},goals,profileId);if(candidate.endpoint_status!=='available')throw policyError('MISSING_GOAL_RELATION_ENDPOINT','No se puede crear una relación con un extremo inexistente.');let duplicate=relations.some(x=>x.profile_id===candidate.profile_id&&x.type===candidate.type&&x.source.goal_id===candidate.source.goal_id&&x.source.node_id===candidate.source.node_id&&x.target.goal_id===candidate.target.goal_id&&x.target.node_id===candidate.target.node_id&&x.status!=='rejected');if(duplicate)throw policyError('DUPLICATE_GOAL_RELATION','Ya existe una relación activa entre esas habilidades.');if(goalRelationCreatesCycle(relations,candidate))throw policyError('GOAL_RELATION_CYCLE','La relación de prerrequisito crearía un ciclo entre metas.');relations.push(candidate);return candidate}
function setGoalRelationStatus(relationId,status,relations=store.goal_relations||[]){if(!GOAL_RELATION_STATES.includes(status))throw policyError('INVALID_GOAL_RELATION_STATUS','El estado de relación no es válido.');let relation=relations.find(x=>x.relation_id===relationId);if(!relation)throw policyError('MISSING_GOAL_RELATION','La relación ya no existe.');relation.status=status;relation.reviewed_at=now();return relation}
