 if(!goal||goal.session?.mode!=='CONTEXT')return {page:'home',context:'none'};
 let stack=Array.isArray(goal.contextStack)?goal.contextStack:[],top=stack[stack.length-1],episode=top?.episode_id&&Array.isArray(goal.repairEpisodes)?goal.repairEpisodes.find(x=>x&&x.episode_id===top.episode_id):null;
